CREATE TABLE core_personas (
 id_persona bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY,
 tipo_persona varchar(30) DEFAULT 'NATURAL', nombres text, apellido_paterno text,
 apellido_materno text, fecha_nacimiento date, activo boolean DEFAULT true,
 fecha_creacion timestamptz DEFAULT now(), fecha_actualizacion timestamptz DEFAULT now()
);
CREATE TABLE cfg_estados_usuario (
 id_estado_usuario integer PRIMARY KEY, codigo text UNIQUE, activo boolean, permite_acceso boolean
);
CREATE TABLE seg_usuarios (
 id_usuario bigint PRIMARY KEY, id_persona bigint, id_estado_usuario integer,
 bloqueado_hasta timestamptz, fecha_actualizacion timestamptz, version_sesiones integer DEFAULT 0
);
CREATE TABLE seg_roles (id_rol bigint PRIMARY KEY, codigo text UNIQUE, activo boolean DEFAULT true, asignable_rrhh boolean DEFAULT true);
CREATE TABLE seg_usuarios_roles (id_usuario bigint, id_rol bigint, activo boolean DEFAULT true);
CREATE TABLE seg_permisos (id_permiso bigint PRIMARY KEY, codigo text, activo boolean DEFAULT true);
CREATE TABLE seg_roles_permisos (id_rol bigint, id_permiso bigint, activo boolean DEFAULT true);
CREATE TABLE rrhh_areas (id_area bigint PRIMARY KEY, activo boolean DEFAULT true);
CREATE TABLE rrhh_cargos (id_cargo bigint PRIMARY KEY, id_area bigint, codigo text, activo boolean DEFAULT true);
CREATE TABLE rrhh_horarios (id_horario bigint PRIMARY KEY, activo boolean DEFAULT true);
CREATE TABLE cfg_tipos_vinculo_laboral (id_tipo_vinculo_laboral integer PRIMARY KEY, activo boolean DEFAULT true);
CREATE TABLE cfg_estados_trabajador (id_estado_trabajador integer PRIMARY KEY, codigo text UNIQUE, activo boolean DEFAULT true);
CREATE SEQUENCE rrhh_worker_code;
CREATE TABLE rrhh_trabajadores (
 id_trabajador bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY,
 codigo text UNIQUE DEFAULT ('T-' || nextval('rrhh_worker_code')),
 id_persona bigint UNIQUE, id_cargo bigint, id_horario bigint, id_estado_trabajador integer,
 id_tipo_vinculo_laboral integer, fecha_ingreso date, fecha_cese date, observaciones text,
 fecha_creacion timestamptz DEFAULT now(), fecha_actualizacion timestamptz DEFAULT now()
);
CREATE TABLE cfg_tipos_documento (
 id_tipo_documento integer PRIMARY KEY, codigo text, longitud_minima integer,
 longitud_maxima integer, solo_numerico boolean, activo boolean DEFAULT true
);
CREATE TABLE cfg_tipos_contacto (id_tipo_contacto integer PRIMARY KEY, codigo text, activo boolean DEFAULT true);
CREATE TABLE core_personas_documentos (
 id_persona_documento bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_persona bigint, id_tipo_documento integer, numero_documento text, principal boolean DEFAULT true,
 activo boolean DEFAULT true, verificado boolean DEFAULT true, fecha_actualizacion timestamptz DEFAULT now()
);
CREATE TABLE core_personas_contactos (
 id_persona_contacto bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_persona bigint, id_tipo_contacto integer, valor text, principal boolean DEFAULT true,
 activo boolean DEFAULT true, verificado boolean DEFAULT true,
 permite_notificaciones boolean DEFAULT false, fecha_actualizacion timestamptz DEFAULT now()
);
CREATE TABLE core_personas_direcciones (
 id_persona_direccion bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_persona bigint, tipo text, direccion text, referencia text, departamento text, provincia text,
 distrito text, pais text, principal boolean DEFAULT true, activo boolean DEFAULT true,
 fecha_actualizacion timestamptz DEFAULT now()
);
CREATE TABLE rrhh_trabajadores_historial_laboral (
 id_historial bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_trabajador bigint,
 id_estado_anterior integer, id_estado_nuevo integer, fecha_ingreso_anterior date,
 fecha_ingreso_nueva date, fecha_cese_anterior date, fecha_cese_nueva date, motivo text, id_usuario_actor bigint
);
CREATE TABLE rrhh_suspensiones_laborales (
 id_suspension bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_trabajador bigint,
 id_usuario_asociado bigint, id_usuario_solicitante bigint, fecha_inicio timestamptz,
 fecha_fin timestamptz, motivo text, estado text, usuario_activo_al_inicio boolean,
 fecha_aplicacion timestamptz, fecha_cancelacion timestamptz, fecha_actualizacion timestamptz,
 error_ultimo text, fecha_finalizacion timestamptz
);
CREATE TABLE rrhh_solicitudes_reincorporacion (
 id_solicitud bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_trabajador bigint,
 id_usuario_solicitante bigint, nueva_fecha_ingreso date, motivo text,
 estado text DEFAULT 'PENDIENTE', id_usuario_resolutor bigint,
 fecha_resolucion timestamptz, motivo_resolucion text, fecha_actualizacion timestamptz
);
CREATE TABLE cfg_tipos_notificacion (id_tipo_notificacion integer PRIMARY KEY, codigo text, activo boolean DEFAULT true);
CREATE TABLE not_notificaciones (
 id_notificacion bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_persona bigint, id_tipo_notificacion integer, titulo text, mensaje text, url_destino text,
 referencia_modulo text, referencia_entidad text, referencia_id varchar, datos_contexto jsonb,
 clave_deduplicacion text UNIQUE, id_usuario_generacion bigint
);
CREATE TABLE core_solicitudes_correccion_identidad (
 id_solicitud bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_persona bigint,
 modulo_origen text, tipo_dato text, id_persona_documento bigint, id_persona_contacto bigint,
 valor_anterior text, valor_propuesto text, motivo text, id_usuario_solicitante bigint,
 estado text DEFAULT 'PENDIENTE', fecha_solicitud timestamptz DEFAULT now(),
 id_tipo_documento_propuesto integer, id_estado_trabajador_previo integer
);
CREATE TABLE seg_control_estados_laborales_usuario (
 id_usuario bigint PRIMARY KEY, id_trabajador bigint, estado_usuario_anterior text,
 estado_usuario_aplicado text, estado_laboral text, reactivacion_automatica_permitida boolean,
 restriccion_laboral_activa boolean, fecha_inicio timestamptz, fecha_actualizacion timestamptz
);
CREATE TABLE seg_restricciones_acceso_manual (id_usuario bigint, restriccion_activa boolean);
CREATE TABLE seg_sesiones (id_usuario bigint, fecha_revocacion timestamptz, motivo_revocacion text);
CREATE TABLE seg_tokens_recuperacion (id_usuario bigint, fecha_uso timestamptz);
CREATE TABLE test_auditoria (id_actor bigint, accion text, entidad text, datos jsonb);

CREATE FUNCTION public.sp_registrar_auditoria(bigint,varchar,varchar,varchar,varchar,varchar,varchar,jsonb)
RETURNS void LANGUAGE sql AS $$
 INSERT INTO test_auditoria (id_actor,accion,entidad,datos) VALUES ($1,$3,$4,$8);
$$;
CREATE FUNCTION public.fn_seguridad_puede_bloquear_persona(bigint,bigint)
RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT NOT EXISTS(SELECT 1 FROM seg_usuarios WHERE id_usuario=$1 AND id_persona=$2)
 AND NOT EXISTS(SELECT 1 FROM seg_usuarios u JOIN seg_usuarios_roles ur USING(id_usuario)
   JOIN seg_roles r USING(id_rol) WHERE u.id_persona=$2 AND ur.activo AND r.activo
   AND r.codigo IN ('GERENCIA','ADMINISTRADOR'));
$$;
CREATE FUNCTION public.fn_seguridad_acceso_laboral_permitido(bigint)
RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM rrhh_trabajadores t JOIN cfg_estados_trabajador e USING(id_estado_trabajador)
   WHERE t.id_persona=$1 AND e.codigo='ACTIVO');
$$;
